grid_out = [[0]*15 for _ in range(18)]

# Hollow triangle 
for r in range(6,9):
    for c in range(4,9):
        if r == 6 and 5 <= c <= 6:
            grid_out[r][c] = 1
        elif r == 7 and c in [4,7]:
            grid_out[r][c] = 1
        elif r == 8 and 3 <= c <= 8:
            grid_out[r][c] = 1
        elif r >= 7 and c == 8:
            grid_out[r][c] = 1
        elif r < 8 and c == 4:
            grid_out[r][c] = 1

# Individual hex for each bar color at rows 9-11, cols 8-12
bar_colors = [2,3,1,8,7]
base_col = 8

for col_idx, col in enumerate(range(base_col, base_col+5)):
    color = bar_colors[col_idx]
    # Small hex centered at row 10
    for r in range(9, 12):
        for c in range(col-1, col+2):
